1	#!/usr/bin/env bun
2	/**
3	 * restore_workspace.ts — put back the working files this issue's agents left last
4	 * run.
5	 *
6	 * Runs before the agent. A first run for an issue restores nothing, which is the
7	 * ordinary case and not a failure: the directory is created either way, so the
8	 * agent finds an empty one rather than a missing one. Those are different things to
9	 * a model reading a tool result, and only one of them invites a retry.
10	 *
11	 * Usage:
12	 *   restore_workspace.ts --type issue|pr --number N --dest /tmp/atomaton-workspace
13	 *     [--repo owner/name]
14	 *
15	 * Writes `root_issue` and `restored` to $GITHUB_OUTPUT so the save step at the end
16	 * of the run writes back to the same place without resolving the chain twice --
17	 * a second resolution could disagree with the first if a parent tag changed
18	 * mid-run, and then the run would read from one workspace and write to another.
19	 */
20	import { appendFileSync, mkdirSync } from "node:fs";
21	import { parseArgs } from "node:util";
22	import { restoreWorkspace, workspaceTargetPrefix } from "./lib/atomaton-data.ts";
23	import { resolveWorkspaceScope } from "../../adapters/github/workspace-scope.ts";
24	import { defineScript } from "./lib/script-ref.ts";
