37	    args: Bun.argv.slice(2),
38	    options: {
39	      type: { type: "string" },
40	      number: { type: "string" },
41	      dest: { type: "string" },
42	      repo: { type: "string" },
43	    },
44	  });
45	
46	  const repo = values.repo ?? process.env.GITHUB_REPOSITORY ?? "";
47	  if (!values.type || !values.number || !values.dest || !repo) {
48	    console.error("usage: restore_workspace.ts --type issue|pr --number N --dest PATH [--repo owner/name]");
49	    process.exit(2);
50	  }
51	
52	  const scope = resolveWorkspaceScope(repo, values.type, values.number);
53	  const prefix = workspaceTargetPrefix(scope.rootIssue);
54	
55	  // Created before the restore attempt, and kept even when there is nothing to
56	  // restore. The agent is told this path exists; a missing directory would make
57	  // that sentence false on every first run.
