1	#!/usr/bin/env bun
2	/**
3	 * save_workspace.ts — persist the working files the agent left behind.
4	 *
5	 * Runs after the agent, and takes the root issue from the restore step's output
6	 * rather than resolving the chain again. Resolving twice invites the two answers
7	 * disagreeing -- a parent tag edited mid-run would have this write to a different
8	 * workspace than the one the agent read from, and nothing would say so.
9	 *
10	 * Usage:
11	 *   save_workspace.ts --root-issue N --source /tmp/atomaton-workspace [--agent NAME]
12	 *
13	 * Best effort. A failure costs the next run its notes, and must not cost this run
14	 * its result -- the work is already committed and the report already posted by the
15	 * time this runs. It says so and exits 0.
16	 */
17	import { existsSync, readdirSync } from "node:fs";
18	import { parseArgs } from "node:util";
19	import { saveWorkspace, workspaceTargetPrefix } from "./lib/atomaton-data.ts";
20	import { defineScript } from "./lib/script-ref.ts";
21	
22	export interface SaveWorkspaceArgs {
23	  "root-issue": string | number;
24	  source: string;
25	  agent?: string;
26	}
27	
28	export const ref = defineScript<SaveWorkspaceArgs>(import.meta.url);
29	
30	function main(): void {
31	  const { values } = parseArgs({
32	    args: Bun.argv.slice(2),
33	    options: {
34	      "root-issue": { type: "string" },
35	      source: { type: "string" },
36	      agent: { type: "string" },
37	    },
38	  });
39	
40	  const root = values["root-issue"];
41	  const source = values.source;
42	  if (!root || !source) {
43	    console.error("usage: save_workspace.ts --root-issue N --source PATH [--agent NAME]");
44	    process.exit(2);
45	  }
46	
47	  if (!existsSync(source)) {
48	    console.error(`[atomaton-workspace] ${source} does not exist; nothing to save`);
49	    return;
50	  }
51	
52	  // An empty workspace is still worth pushing: it is how a deletion takes effect.
53	  // The agent removing its notes and this skipping the save would leave them there
54	  // for the next run, which is the shape where deletions silently do not happen.
55	  const count = readdirSync(source).length;
56	  const prefix = workspaceTargetPrefix(root);
57	  const saved = saveWorkspace(
58	    prefix,
59	    source,
60	    `atomaton: workspace for issue #${root}${values.agent ? ` (${values.agent})` : ""} — ${count} entries`,
61	  );
62	
63	  console.error(
64	    saved
65	      ? `[atomaton-workspace] saved ${count} entries to ${prefix}`
66	      : `[atomaton-workspace] WARN could not save ${prefix}; the next run on this issue starts without these files`,
67	  );
68	}
